using System;using System.IO;using System.Reflection;using System.Runtime.CompilerServices;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using TopoptLab.GH;
class SnapshotCacheProbe {
 [STAThread]static int Main(string[] args){string[] paths={args[0],args[1],args[2]};AppDomain.CurrentDomain.AssemblyResolve+=delegate(object sender,ResolveEventArgs e){foreach(string p in paths)foreach(string ext in new[]{".dll",".gha"}){string f=Path.Combine(p,new AssemblyName(e.Name).Name+ext);if(File.Exists(f))return Assembly.LoadFrom(f);}return null;};try{Test(args[3]);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Save(string path,string status,int iteration,string id,DateTime time){File.WriteAllText(path,new JObject{{"job_id",id},{"status",status},{"iteration",iteration}}.ToString(Formatting.None));File.SetLastWriteTimeUtc(path,time);}
 [MethodImpl(MethodImplOptions.NoInlining)]static void Test(string root){string folder=Path.Combine(root,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var time=new DateTime(2026,1,1,0,0,0,DateTimeKind.Utc);string progress=Path.Combine(folder,"progress.json"),result=Path.Combine(folder,"result.json");var job=new WorkerJob{Id="first",Folder=folder};Check(job.Snapshot()==null,"Missing snapshot should be null");Save(progress,"running",1,job.Id,time);var first=job.Snapshot();Check((int)first["iteration"]==1,"First progress missing");Check(Object.ReferenceEquals(first,job.Snapshot()),"Unchanged snapshot reparsed");Save(progress,"running",2,job.Id,time.AddSeconds(2));var changed=job.Snapshot();Check(!Object.ReferenceEquals(first,changed)&&(int)changed["iteration"]==2,"Changed progress remained cached");
 File.WriteAllText(progress,"{bad-json");File.SetLastWriteTimeUtc(progress,time.AddSeconds(4));bool invalid=false;try{job.Snapshot();}catch(JsonReaderException){invalid=true;}Check(invalid,"Incomplete JSON was silently accepted");Save(progress,"running",2,job.Id,time.AddSeconds(2));var recovered=job.Snapshot();Check(!Object.ReferenceEquals(changed,recovered)&&(int)recovered["iteration"]==2,"Parse failure poisoned or retained cache");
 string replacement=Path.Combine(folder,"progress.tmp");Save(replacement,"running",3,job.Id,time.AddSeconds(6));File.Replace(replacement,progress,null);Check((int)job.Snapshot()["iteration"]==3,"Atomic replacement remained cached");
 // A terminal file is authoritative even when stale progress is still present.
 Save(result,"completed",2,job.Id,time.AddSeconds(2));var completed=job.Snapshot();Check((string)completed["status"]=="completed","Terminal result not prioritized");Check(Object.ReferenceEquals(completed,job.Snapshot()),"Completed result reparsed");File.Delete(result);File.Delete(progress);Check(job.Snapshot()==null,"Removed files returned stale data");Save(progress,"running",3,job.Id,time.AddSeconds(2));Check((int)job.Snapshot()["iteration"]==3,"Recreated file not read");
 string other=Path.Combine(root,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(other);Save(Path.Combine(other,"progress.json"),"running",4,job.Id,time.AddSeconds(2));job.Folder=other;Check((int)job.Snapshot()["iteration"]==4,"Folder change reused previous cache");job.Id="other";bool wrong=false;try{job.Snapshot();}catch(InvalidDataException){wrong=true;}Check(wrong,"Changed job identifier bypassed validation");Save(Path.Combine(other,"progress.json"),"completed",5,job.Id,time.AddSeconds(2));Check((string)job.Snapshot()["status"]=="completed","Progress terminal transition missing");Console.WriteLine("PASS snapshot cache: unchanged/changed/atomically replaced file, completion priority, parse recovery, deletion, folder and job ID invalidation");}
}
